  'anthropicBaseUrl', 'geminiBaseUrl', 'customBaseUrl', 'openaiApiKey',
  'openrouterApiKey', 'anthropicApiKey', 'geminiApiKey', 'customApiKey',
  'embedModel', 'chatModel', 'embedConcurrency', 'ragTopK', 'maxTokens',
  'piiReduction',
