  await withIsolatedStore(async (store) => {
    const vault = (await store.listVaults()).find(item => item.name === 'Personal');
    const externalMeta = path.join(store.ROOT, 'outside-meta.json');
    fs.writeFileSync(externalMeta, JSON.stringify({
